from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session

from app import crud, schemas
from app.db.session import get_db
from app.models.task import TaskStatus

router = APIRouter(prefix="/tasks", tags=["tasks"])


@router.post("", response_model=schemas.TaskOut, status_code=201)
def create_task(payload: schemas.TaskCreate, db: Session = Depends(get_db)):
    return crud.create_task(db, payload)


@router.post("/bulk-assign", response_model=list[schemas.TaskOut])
def bulk_assign_tasks(payload: schemas.TaskBulkAssign, db: Session = Depends(get_db)):
    if crud.get_user(db, payload.assignee_id) is None:
        raise HTTPException(status_code=400, detail="assignee_id must reference an existing user")
    if len(payload.task_ids) == 0:
        raise HTTPException(status_code=400, detail="task_ids must not be empty")

    found = crud.get_tasks_by_ids(db, payload.task_ids)
    missing = [tid for tid in payload.task_ids if tid not in found]
    if missing:
        raise HTTPException(status_code=404, detail=f"tasks not found: {missing}")

    current = crud.count_active_tasks_for_assignee(db, payload.assignee_id)
    if current + len(payload.task_ids) > crud.MAX_ACTIVE_TASKS_PER_ASSIGNEE:
        raise HTTPException(
            status_code=409, detail="batch would exceed assignee's maximum active tasks"
        )

    tasks = [found[tid] for tid in payload.task_ids]
    for task in tasks:
        task.assignee_id = payload.assignee_id
        db.add(task)
    db.commit()
    for task in tasks:
        db.refresh(task)
    return tasks


@router.get("", response_model=list[schemas.TaskOut])
def list_tasks(
    project_id: int | None = None,
    status: TaskStatus | None = None,
    assignee_id: int | None = None,
    skip: int = 0,
    limit: int = 100,
    db: Session = Depends(get_db),
):
    return crud.list_tasks(
        db, project_id=project_id, status=status, assignee_id=assignee_id, skip=skip, limit=limit,
    )


@router.get("/{task_id}", response_model=schemas.TaskOut)
def get_task(task_id: int, db: Session = Depends(get_db)):
    task = crud.get_task(db, task_id)
    if task is None:
        raise HTTPException(status_code=404, detail="task not found")
    return task


@router.patch("/{task_id}", response_model=schemas.TaskOut)
def update_task(task_id: int, payload: schemas.TaskUpdate, db: Session = Depends(get_db)):
    task = crud.get_task(db, task_id)
    if task is None:
        raise HTTPException(status_code=404, detail="task not found")
    return crud.update_task(db, task, payload)


@router.delete("/{task_id}", status_code=204)
def delete_task(task_id: int, db: Session = Depends(get_db)):
    task = crud.get_task(db, task_id)
    if task is None:
        raise HTTPException(status_code=404, detail="task not found")
    crud.delete_task(db, task)

